(function(){
if(!document.getElementById('q'))return;
const q=document.getElementById('q'),res=document.getElementById('results'),
      br=document.getElementById('browse');
const esc=s=>s.replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
// tolerate plurals and partial words: every term must appear as a substring, and a
// trailing s is optional on each term
const terms=t=>t.toLowerCase().split(/\s+/).filter(Boolean)
  .map(w=>w.replace(/s$/,''));
const hay=r=>(r.n+' '+r.d+' '+r.c+' '+(r.t||'')).toLowerCase();
function mark(text,ts){
  let out=esc(text);
  ts.forEach(t=>{
    if(t.length<2)return;
    out=out.replace(new RegExp('('+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'s?)','gi'),
      '<mark>$1</mark>');
  });
  return out;
}
function run(){
  const raw=q.value.trim();
  history.replaceState(null,'',raw?('#q='+encodeURIComponent(raw)):location.pathname);
  if(raw.length<2){res.classList.add('hidden');br.classList.remove('hidden');return;}
  br.classList.add('hidden');res.classList.remove('hidden');
  const ts=terms(raw);
  const hits=R.filter(r=>{const h=hay(r);return ts.every(t=>h.includes(t));});
  if(!hits.length){
    res.innerHTML='<p class="hint">Nothing matches &ldquo;'+esc(raw)+'&rdquo;. '+
      'If you know a resource that belongs here, '+
      '<a href="mailto:info@biodiversitygroup.org?subject=Conservation%20Portal%3A%20suggest%20a%20resource">'+
      'send it over</a>.</p>';return;}
  const shown=hits.slice(0,150);
  res.innerHTML='<div class="rule"><span class="eyebrow">'+hits.length+' result'+
    (hits.length===1?'':'s')+(hits.length>shown.length?', showing '+shown.length:'')+
    '</span></div><ul class="list">'+
    shown.map(r=>'<li class="item"><a href="'+esc(r.u)+'" target="_blank" rel="noopener">'+
      '<span class="nm">'+mark(r.n,ts)+'<span class="arw" aria-hidden="true">&#8599;</span>'+
      '</span><p>'+mark(r.d,ts)+'</p></a>'+
      '<a href="/'+r.s+'/" class="hint" style="display:block;padding:0 22px 14px;'+
      'font-size:12.5px;margin:0">in '+esc(r.c)+'</a></li>').join('')+'</ul>';
}
q.addEventListener('input',run);
addEventListener('keydown',e=>{
  if(e.key==='/'&&document.activeElement!==q){e.preventDefault();q.focus();}
  if(e.key==='Escape'&&document.activeElement===q){q.value='';run();q.blur();}
});
const m=location.hash.match(/^#q=(.*)$/);
if(m){q.value=decodeURIComponent(m[1]);run();}
})();
